{"version":3,"file":"page-0dHdwonT.js","sources":["../../../../pages/conclusion/key-takeaways/page.js"],"sourcesContent":["import {html, css} from 'lit';
import {customElement} from 'lit/decorators.js';
import {AIUXElement} from '@servicenow/aiux/aiux-components-core';
import {i18n} from '@servicenow/aiux/aiux-services';
import {setDocumentTitle} from '../../../utils/document-title.js';

@customElement('x-snc-wdf-lab-key-takeaways-page')
export default class KeyTakeawaysPage extends AIUXElement {
  static styles = css`
    :host {
      display: block;
      min-height: 100%;
      container-type: inline-size;
    }
    figure {
      margin: 0;
    }
  `;

  firstUpdated() {
    setDocumentTitle(i18n.getMessage('Key Takeaways'));
  }

  static async loader(ctx) {
    return {basePath: ctx.basePath};
  }

  render() {
    const {basePath} = this.loaderData || {};

    return html`
      <div class="mx-auto flex max-w-4xl flex-col gap-8 p-4 lg:p-8">
        <header class="flex flex-col gap-2">
          <span class="aiux-badge aiux-badge-primary aiux-badge-outline w-fit">
            ${i18n.getMessage('Conclusion')}
          </span>
          <h2 class="text-3xl font-bold text-text-primary">
            ${i18n.getMessage('Key Takeaways')}
          </h2>
        </header>

        <figure>
          <img
            src="${basePath.replace(/^\/aiux/, '')}/public/wdf/conclusion/sc_slide_key_takeaways.png"
            alt="${i18n.getMessage('Key takeaways summary slide')}"
            class="w-full rounded-xl border border-base-300"
          />
        </figure>

        <a class="aiux-btn aiux-btn-outline w-fit" href="${basePath}/home">
          ${i18n.getMessage('Take me back to main page')}
        </a>
      </div>
    `;
  }
}
